/**
* Computes the modified Bessel function of the second kind of order zero.
*
* ## Notes
*
* -   The function has a logarithmic singularity at `x = 0`.
* -   Accuracy for subnormal `x` is poor due to underflow.
*
* @param x    input value
* @return     evaluated modified Bessel function
*
* @example
* double y = stdlib_base_besselk0( 1.0 );
* // returns ~0.421024
*/
double stdlib_base_besselk0( const double x ) {
	double a;
	double ex;

	if ( x < 0.0 ) {
		return 0.0 / 0.0; // NaN
	}
	if ( x == 0.0 ) {
		return STDLIB_CONSTANT_FLOAT64_PINF;
	}
	if ( x == STDLIB_CONSTANT_FLOAT64_PINF ) {
		return 0.0;
	}

	/* Small-x: x <= 1 */
	if ( x <= 1.0 ) {
		a = ( x * x ) * 0.25;
		a = ( rational_p1q1( a ) + 1.1372509002685547 ) * a + 1.0;
		return poly_p2( x * x ) - stdlib_base_ln( x ) * a;
	}

	/* Large-x */
	if ( x < 709.782712893384 ) {
		return ( rational_p3q3( 1.0 / x ) + 1.0 ) *
			stdlib_base_exp( -x ) / stdlib_base_sqrt( x );
	}

	/* Overflow-safe exponential split */
	ex = stdlib_base_exp( -0.5 * x );
	return ( rational_p3q3( 1.0 / x ) + 1.0 ) *
		ex / stdlib_base_sqrt( x ) * ex;
}
